// One worker. Identical branch order in both modes. Optional solver emits all 76-edge legal cores; the driver deduplicates and completes their port rows.
use std::io::{self,Read};type A=[u32;26];type E=(usize,usize);const F:u32=(1<<26)-1;
fn blue(a:&A,mut m:u32,k:u32)->bool{if k==0{return true}while m.count_ones()>=k{let i=m.trailing_zeros()as usize;m&=m-1;if blue(a,m&!a[i],k-1){return true}}false}
fn toggle(a:&mut A,(i,j):E){a[i]^=1<<j;a[j]^=1<<i}fn safe(a:&A,(i,j):E)->bool{!blue(a,F&!(a[i]|a[j]),6)}
fn sets(a:&A,mut m:u32,k:u32,s:u32,out:&mut Vec<u32>){if k==0{out.push(s);return}while m.count_ones()>=k{let i=m.trailing_zeros()as usize;m&=m-1;sets(a,m&!a[i],k-1,s|1<<i,out)}}
fn clique(adj:&[Vec<u64>],mut p:Vec<u64>,k:u32)->bool{if k==0{return true}let mut n=p.iter().map(|x|x.count_ones()).sum::<u32>();for w in 0..p.len(){while p[w]!=0{if n<k{return false}let i=64*w+p[w].trailing_zeros()as usize;p[w]&=p[w]-1;n-=1;if clique(adj,p.iter().zip(&adj[i]).map(|(x,y)|x&y).collect(),k-1){return true}}}false}
fn solve(a:&mut A,p:&[E],need:usize,z:usize,st:&mut [u64;6]){st[4]+=1;if p.len()<need{return}if need==0{if a.iter().all(|v|v.count_ones()<=7){st[5]+=1;println!("core {} {:?}",z,a)}return}let ok:Vec<_>=p.iter().copied().filter(|&e|safe(a,e)).collect();if ok.len()<need{return}for t in 0..=ok.len()-need{toggle(a,ok[t]);solve(a,&ok[t+1..],need-1,z,st);toggle(a,ok[t])}}
struct Site{z:usize,a:A,old:Vec<E>,probes:Vec<u32>,on:bool,detail:bool}
impl Site{fn prefix(&self,g:&mut A,adds:[E;2],tri:&[Vec<E>],cut:&mut Vec<E>,ban:&mut Vec<E>,st:&mut [u64;6]){if let Some(t)=tri.iter().find(|t|!t.iter().any(|e|cut.contains(e))){let len=ban.len();for &e in t{if ban.contains(&e)||!safe(g,e){continue}toggle(g,e);cut.push(e);self.prefix(g,adds,tri,cut,ban,st);cut.pop();toggle(g,e);ban.push(e)}ban.truncate(len);return}if cut.iter().any(|e|!tri.iter().any(|t|t.contains(e)&&t.iter().filter(|f|cut.contains(f)).count()==1)){return}st[1]+=1;let mut fixed=*g;let optional:Vec<_>=self.old.iter().copied().filter(|&(i,j)|g[i]>>j&1!=0 && safe(g,(i,j))).collect();for &e in &optional{toggle(&mut fixed,e)}let mut rows=vec![];sets(&fixed,F,7,0,&mut rows);let n=rows.len();if n<8{return}let w=(n+63)/64;let mut all=vec![!0u64;w];if n%64!=0{all[w-1]=(1<<(n%64))-1}let mut adj=vec![all.clone();n];let mut seven=vec![];sets(g,F,7,0,&mut seven);for q in seven{let mut mask=vec![0;w];let mut missed=vec![];for(i,&s)in rows.iter().enumerate(){if q&s==0{missed.push(i);mask[i/64]|=1<<(i%64)}}for i in missed{for j in 0..w{adj[i][j]&=!mask[j]}}}for i in 0..n{adj[i][i/64]&=!(1<<(i%64))}if !clique(&adj,all,8){return}st[2]+=1;let mut fail=0;if self.on{for &q in &self.probes{if adds.iter().any(|&(i,j)|q>>i&q>>j&1!=0){continue}let mut hits=vec![0;w];for(i,&s)in rows.iter().enumerate(){if s&q!=0{hits[i/64]|=1<<(i%64)}}if !clique(&adj,hits,6){fail=q;break}}}if self.detail{println!("prefix {} {} {} {} {} {} {:?}",self.z,adds[0].0,adds[0].1,adds[1].0,adds[1].1,fail,g)}if fail!=0{st[3]+=1;return}let edges=g.iter().map(|s|s.count_ones()as usize).sum::<usize>()/2;if edges>=76{solve(g,&optional,edges-76,self.z,st)}}
fn run(&self,cross:&[E])->[u64;6]{let mut st=[0;6];for(k,&e)in cross.iter().enumerate(){for &f in &cross[k+1..]{st[0]+=1;let mut g=self.a;toggle(&mut g,e);toggle(&mut g,f);let mut tri=vec![];for &(i,j)in &[e,f]{let mut m=g[i]&g[j];while m!=0{let t=m.trailing_zeros()as usize;m&=m-1;let mut v:Vec<_>=[(i,t),(j,t)].iter().map(|&(u,v)|(u.min(v),u.max(v))).filter(|x|*x!=e&&*x!=f).collect();v.sort();if !tri.contains(&v){tri.push(v)}}}self.prefix(&mut g,[e,f],&tri,&mut vec![],&mut vec![],&mut st)}}st}}
fn main(){let args:Vec<_>=std::env::args().collect();let mut s=String::new();io::stdin().read_to_string(&mut s).unwrap();let b:Vec<u32>=s.split_whitespace().map(|x|x.parse().unwrap()).collect();for z in 0..27{if args.len()>3 && z!=args[3].parse::<usize>().unwrap(){continue}let v:Vec<_>=(0..27).filter(|&i|i!=z).collect();let mut a=[0;26];let(mut old,mut cross)=(vec![],vec![]);let mut bluez=0;for i in 0..26{if b[z]>>v[i]&1==0{bluez|=1<<i}for j in i+1..26{if b[v[i]]>>v[j]&1!=0{old.push((i,j));toggle(&mut a,(i,j))}else if (b[z]>>v[i]^b[z]>>v[j])&1!=0{cross.push((i,j))}}}let mut probes=vec![];if args[1]=="on"{sets(&a,bluez,6,0,&mut probes)}let site=Site{z,a,old,probes,on:args[1]=="on",detail:args[2]=="detail"};println!("done {} {:?}",z,site.run(&cross))}}
